package com.fakelegacy.catalog;

import java.math.BigDecimal;

import jakarta.persistence.PostLoad;
import jakarta.persistence.PreUpdate;

public class PriceHistoryListener {

    private static final BigDecimal HALF = new BigDecimal("0.5");

    @PostLoad
    public void remember(Product p) {
        p.setPreviousBasePrice(p.getBasePrice());
        p.setPreviousSalePrice(p.getSalePrice());
    }

    @PreUpdate
    public void checkDrop(Product p) {
        BigDecimal previous = p.getPreviousBasePrice();
        if (previous != null && p.getBasePrice().compareTo(previous.multiply(HALF)) < 0) {
            throw new PriceRuleException("base price cannot drop by more than 50% in one operation");
        }
    }
}
